from typing import Any, Dict, List, Text

import structlog
from qdrant_client import AsyncQdrantClient

from rasa.core.information_retrieval import (
    InformationRetrieval,
    InformationRetrievalException,
    SearchResultList,
)
from rasa.core.information_retrieval.models import Document
from rasa.shared.providers.embedding.embedding_utils import aembed_query
from rasa.utils.endpoints import EndpointConfig

logger = structlog.get_logger()

DEFAULT_CONTENT_PAYLOAD_KEY = "text"
DEFAULT_METADATA_PAYLOAD_KEY = "metadata"
DEFAULT_SEARCH_K = 4
DEFAULT_PORT = 6333
DEFAULT_GRPC_PORT = 6334
DEFAULT_PREFER_GRPC = False
DEFAULT_TIMEOUT = 5


class PayloadNotFoundException(InformationRetrievalException):
    """Exception raised for errors in missing payloads."""

    def __init__(self, message: str) -> None:
        self.message = message
        super().__init__()

    def __str__(self) -> str:
        return self.base_message + self.message + f"{self.__cause__}"


class QdrantInformationRetrievalException(InformationRetrievalException):
    """Exception raised for errors in the Qdrant vector store."""

    def __init__(self, message: str) -> None:
        self.message = message
        super().__init__()

    def __str__(self) -> str:
        return self.base_message + self.message + f"{self.__cause__}"


class Qdrant_Store(InformationRetrieval):
    """Qdrant vector store backed by the native ``qdrant-client``."""

    def connect(
        self,
        config: EndpointConfig,
    ) -> None:
        """Connect to the Qdrant system."""
        params = config.kwargs
        # An empty string denotes the default (unnamed) vector.
        self.vector_name = params.get("vector_name") or ""
        self.collection_name = str(params.get("collection"))
        self.content_payload_key = params.get(
            "content_payload_key", DEFAULT_CONTENT_PAYLOAD_KEY
        )
        self.metadata_payload_key = params.get(
            "metadata_payload_key", DEFAULT_METADATA_PAYLOAD_KEY
        )
        self.client = AsyncQdrantClient(
            location=params.get("location"),
            url=params.get("url"),
            port=int(params.get("port", DEFAULT_PORT)),
            grpc_port=int(params.get("grpc_port", DEFAULT_GRPC_PORT)),
            prefer_grpc=bool(params.get("prefer_grpc", DEFAULT_PREFER_GRPC)),
            https=params.get("https"),
            api_key=params.get("api_key"),
            prefix=params.get("prefix"),
            timeout=int(params.get("timeout", DEFAULT_TIMEOUT)),
            host=params.get("host"),
            path=params.get("path"),
        )

    def _point_to_document(self, payload: Dict[str, Any] | None) -> Document:
        payload = payload or {}
        if self.content_payload_key not in payload:
            raise PayloadNotFoundException(
                "Payload not found in the Qdrant response. Please make sure "
                "the `content_payload_key`and `metadata_payload_key` are correct "
                f"in the Qdrant configuration. Error: missing key "
                f"'{self.content_payload_key}'"
            )
        text = payload.get(self.content_payload_key)
        metadata = payload.get(self.metadata_payload_key) or {}
        return Document(text=text, metadata=metadata)

    async def search(
        self, query: Text, tracker_state: Dict[str, Any], threshold: float = 0.0
    ) -> SearchResultList:
        """Search for a document in the Qdrant vector store.

        Args:
            query: The query to search for.
            tracker_state: The state of the tracker (unused by Qdrant).
            threshold: minimum similarity score to consider a document a match.
                Forwarded to the server as ``score_threshold`` (Qdrant uses
                min-similarity semantics: higher = better).

        Returns:
            A list of documents that match the query.
        """
        logger.debug("information_retrieval.qdrant_store.search", query=query)
        try:
            # Embed the query using the embedding client
            embedding = await aembed_query(self.embeddings, query)
            # Search for the embedding in the Qdrant collection
            query_kwargs: Dict[str, Any] = dict(
                collection_name=self.collection_name,
                query=embedding,
                limit=DEFAULT_SEARCH_K,
                score_threshold=threshold,
                with_payload=True,
            )
            if self.vector_name:
                query_kwargs["using"] = self.vector_name
            response = await self.client.query_points(**query_kwargs)
        except PayloadNotFoundException:
            raise
        except Exception as e:
            raise QdrantInformationRetrievalException(
                f"Failed to search the Qdrant vector store. Encountered error: {e}"
            ) from e

        # Convert the response to a list of documents
        points = getattr(response, "points", response)
        documents: List[Document] = [
            self._point_to_document(getattr(point, "payload", None)) for point in points
        ]
        # Convert the list of documents to a SearchResultList object
        return SearchResultList.from_document_list(documents)
